      SUBROUTINE TWIT3ECC     DETERMINES CONTRIBUTION OF THIRD-ORDER TRANSFER MATRIX TOC     TRANSFORM OF PARTIALS OF ETA FUNCTIONCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETATC.CIN'      INCLUDE 'U.CIN'CC     TRANSFORM DERIVATIVE OF ETAC      DO 20 J = 1, 5      SS = 0.0      IND = 0      DO 10 L3 = 1, 6      DO 10 L2 = 1, L3      DO 10 L1 = 1, L2      IND = IND + 1      SS = SS + U(J,IND)*(ETA(L1)*ETA(L2)*ETAV(L3,NV2)     1                  + ETA(L1)*ETAV(L2,NV2)*ETA(L3)     2                  + ETAV(L1,NV2)*ETA(L2)*ETA(L3))   10 CONTINUE      ETAT(J) = ETAT(J) + SS   20 CONTINUEC      RETURN      END